"use client";

import { cn } from "@repo/design-system/lib/utils";
import { useTheme } from "next-themes";
import { useCallback, useEffect, useState } from "react";
import { PlusGridItem } from "./plus-grid";

const OPTIONS = [
  { label: "light", value: "light" },
  { label: "dark", value: "dark" },
  { label: "system", value: "system" },
] as const;

// One group on the page, so a literal name is enough and beats a generated
// id that would have to survive the mount gate below.
const GROUP = "theme";

function ThemeOption({
  label,
  selected,
  value,
}: {
  label: string;
  selected: boolean;
  value: string;
}) {
  const { setTheme } = useTheme();
  const select = useCallback(() => setTheme(value), [setTheme, value]);

  return (
    <label className="cursor-pointer">
      {/* A real radio group: the platform gives one tab stop, arrow-key
          movement between the three, and the right role and checked state
          without a line of keyboard code here. */}
      <input
        checked={selected}
        className="peer sr-only"
        name={GROUP}
        onChange={select}
        type="radio"
        value={value}
      />
      <span
        className={cn(
          "block rounded-full px-2.5 py-1 font-mono font-semibold text-[0.7rem] uppercase tracking-[0.16em] transition-colors",
          "peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-ht-cyan-600 dark:peer-focus-visible:outline-ht-cyan-400",
          selected
            ? "bg-background text-foreground shadow-sm"
            : "text-muted-foreground hover:text-foreground"
        )}
      >
        {label}
      </span>
    </label>
  );
}

/**
 * The theme control: light, dark, or follow the OS. Three positions visible
 * at once rather than a dropdown, because which one is active is the fact
 * worth showing, and one click is the whole interaction.
 *
 * It renders nothing until mounted. The choice lives in localStorage, so the
 * server cannot know it — a server-rendered control would either mark the
 * wrong option for a frame or, with JavaScript off, sit there being a switch
 * that switches nothing. Nothing shifts when it appears: the row is
 * `justify-between` with the logo setting its height, so this arrives in
 * empty space at the right edge.
 */
export function ThemeSwitch({
  variant = "light",
}: {
  variant?: "light" | "dark";
}) {
  const { theme } = useTheme();
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) {
    return null;
  }

  return (
    <PlusGridItem className="py-3" variant={variant}>
      <fieldset>
        <legend className="sr-only">Theme</legend>
        <div className="flex items-center gap-0.5 rounded-full border border-foreground/10 bg-muted/40 p-0.5">
          {OPTIONS.map((option) => (
            <ThemeOption
              key={option.value}
              label={option.label}
              selected={theme === option.value}
              value={option.value}
            />
          ))}
        </div>
      </fieldset>
    </PlusGridItem>
  );
}

