() => {
  const group = document.querySelector('[role="radiogroup"]');
  const widths = [...group.querySelectorAll('label span')].map(s => Math.round(s.getBoundingClientRect().width));
  const gr = group.getBoundingClientRect();
  return { groupW: Math.round(gr.width), groupLeft: Math.round(gr.left), chipWidths: widths };
}

() => {
  const group = document.querySelector('[role="radiogroup"]');
  const inputs = [...group.querySelectorAll('input')];
  const measure = () => {
    const spans = [...group.querySelectorAll('label span')];
    return { groupW: Math.round(group.getBoundingClientRect().width), chips: spans.map(s => Math.round(s.getBoundingClientRect().width)) };
  };
  const before = measure();
  inputs[2].focus();
  const focused = measure();
  return { before, afterFocusOnChecked: focused, activeIsRadio: document.activeElement.type === 'radio' };
}

async () => {
  const group = document.querySelector('[role="radiogroup"]');
  const inputs = [...group.querySelectorAll('input')];
  const measure = () => ({
    groupW: Math.round(group.getBoundingClientRect().width),
    chips: [...group.querySelectorAll('label span')].map(s => Math.round(s.getBoundingClientRect().width)),
  });
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  const before = measure();
  inputs[2].focus();
  await wait(400);
  const afterFocus = measure();
  inputs[2].blur();
  await wait(400);
  const afterBlur = measure();
  return { before, afterFocus, afterBlur };
}

async () => {
  const el = document.querySelector('[role="radiogroup"]');
  const out = { role: el.getAttribute('role'), label: el.getAttribute('aria-label') };
  if (typeof window.getComputedAccessibleNode === 'function') {
    const node = await window.getComputedAccessibleNode(el);
    out.computedRole = node.role;
    out.computedName = node.name;
  } else {
    out.computedApi = 'unavailable';
  }
  return out;
}

async () => {
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  await wait(400);
  const group = document.querySelector('[role="radiogroup"]');
  return {
    groupW: Math.round(group.getBoundingClientRect().width),
    chips: [...group.querySelectorAll('label span')].map(s => Math.round(s.getBoundingClientRect().width)),
    hoverMatches: group.matches(':hover'),
    parentHover: group.parentElement.matches(':hover'),
  };
}

