import type { ThemeProviderProps } from "next-themes";
import { ThemeProvider as NextThemeProvider } from "next-themes";

// Re-exported so consumers read the theme through the same module instance
// that provides it. next-themes keeps its context in module scope, and an app
// that depended on next-themes directly could resolve a second copy whose
// context is permanently empty.
export { useTheme } from "next-themes";

export const ThemeProvider = ({
  children,
  ...properties
}: ThemeProviderProps) => (
  <NextThemeProvider
    attribute="class"
    defaultTheme="system"
    disableTransitionOnChange
    enableSystem
    {...properties}
  >
    {children}
  </NextThemeProvider>
);

