  const g = document.querySelector('[role="radiogroup"]');
  const collapsed = Math.round(g.getBoundingClientRect().width);
  g.querySelector('input:checked').focus();
  await new Promise(r => setTimeout(r, 400));
  const open = Math.round(g.getBoundingClientRect().width);
