input.function:
async () => {
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  const g = () => document.querySelector('[role="radiogroup"]');
  const chipOf = (v) => [...g().querySelectorAll('label')].find(l => l.querySelector('input').value === v).querySelector('span');
  const out = { groupW: Math.round(g().getBoundingClientRect().width), perTheme: {} };
  for (const v of ['light', 'dark', 'system']) {
    const input = [...g().querySelectorAll('input')].find(i => i.value === v);
    input.click();
    document.activeElement.blur();
    await wait(300);
    const rest = Math.round(chipOf(v).getBoundingClientRect().left);
    input.focus();
    await wait(300);
    const focused = Math.round(chipOf(v).getBoundingClientRect().left);
    document.activeElement.blur();
    await wait(300);
    out.perTheme[v] = { restLeft: rest, focusedLeft: focused, shiftPx: focused - rest, groupW: Math.round(g().getBoundingClientRect().width) };
  }
  return out;
}

