async () => {
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  const cv = document.createElement('canvas'); cv.width=1; cv.height=1;
  const ctx = cv.getContext('2d', { willReadFrequently: true });
  const over = (css, bd) => { ctx.clearRect(0,0,1,1); ctx.fillStyle=bd; ctx.fillRect(0,0,1,1); ctx.fillStyle=css; ctx.fillRect(0,0,1,1); const d=ctx.getImageData(0,0,1,1).data; return [d[0],d[1],d[2]]; };
  const srgb=(c)=>{c/=255;return c<=0.03928?c/12.92:Math.pow((c+0.055)/1.055,2.4);};
  const lum=([r,g,b])=>0.2126*srgb(r)+0.7152*srgb(g)+0.0722*srgb(b);
  const ratio=(a,b)=>{const l1=lum(a),l2=lum(b);return Math.round(((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05))*100)/100;};
  const hex=(a)=>'#'+a.map(n=>n.toString(16).padStart(2,'0')).join('');
  const out = {};
  for (const t of ['light','dark']) {
    const g = document.querySelector('[role="radiogroup"]');
    [...g.querySelectorAll('input')].find(i=>i.value===t).click();
    document.activeElement.blur();
    await wait(350);
    const gs = getComputedStyle(g);
    const page = over(getComputedStyle(document.body).backgroundColor, '#808080');
    const pill = over(gs.backgroundColor, hex(page));
    const chips = [...g.querySelectorAll('label > span')];
    const sel = chips.find(c=>c.parentElement.querySelector('input').checked);
    const un = chips.find(c=>c!==sel);
    const selCs = getComputedStyle(sel), unCs = getComputedStyle(un);
    const selFill = over(selCs.backgroundColor, hex(pill));
    const selText = over(selCs.color, hex(selFill));
    const unText = over(unCs.color, hex(pill));
    out[t] = {
      swatch: { page: hex(page), selFill: hex(selFill), selText: hex(selText), unselText: hex(unText) },
      'selected label on its chip (4.5)': ratio(selText, selFill),
      'unselected label on pill (4.5)': ratio(unText, pill),
      'SELECTED FILL vs pill — state (3.0)': ratio(selFill, pill),
      'selected fill vs page (3.0)': ratio(selFill, page),
    };
  }
  return out;
}

