  const probe = document.createElement('span'); probe.style.display='none'; document.body.appendChild(probe);
  const resolve = (css) => { probe.style.color=''; probe.style.color=css; return getComputedStyle(probe).color; };
  const cv=document.createElement('canvas');cv.width=1;cv.height=1;
  const ctx=cv.getContext('2d',{willReadFrequently:true});
  const over=(css,bd)=>{ctx.clearRect(0,0,1,1);ctx.fillStyle=bd;ctx.fillRect(0,0,1,1);ctx.fillStyle=css;ctx.fillRect(0,0,1,1);const d=ctx.getImageData(0,0,1,1).data;return [d[0],d[1],d[2]];};
  const srgb=(c)=>{c/=255;return c<=0.03928?c/12.92:Math.pow((c+0.055)/1.055,2.4);};
  const lum=([r,g,b])=>0.2126*srgb(r)+0.7152*srgb(g)+0.0722*srgb(b);
  const ratio=(a,b)=>{const l1=lum(a),l2=lum(b);return Math.round(((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05))*100)/100;};
